mapper.select:
SELECT a.bmt01_buy_id AS buy_id , a.bmt01_buy_date AS buy_date , a.bmt01_provide_content_cd AS provide_content_code , f_cdnm('ProvideContentCode', a.bmt01_provide_content_cd, a.bmt01_company_id, a.bmt01_buy_date) AS provide_content_name , a.bmt01_buy_qty AS buy_qty , a.bmt01_buy_amt AS buy_amt , COALESCE(c.biz02_count, 0) AS total_peple , a.bmt01_buy_amt / a.bmt01_buy_qty AS average_price , a.bmt01_buy_qty - COALESCE(c.biz02_count, 0) AS left_qty , a.bmt01_person_id AS person_id , f_emp_kor_nm(a.bmt01_person_id) AS person_name , a.bmt01_appr_id AS appr_id , f_cdnm('AprStatusCode', b.apr01_status_cd, a.bmt01_company_id, f_sysdate()) AS appr_status_name FROM bmt01_buy a LEFT OUTER JOIN apr01_appr b ON b.apr01_appr_id = a.bmt01_appr_id LEFT OUTER JOIN ( SELECT biz01_buy_id , COUNT(*) biz02_count FROM biz01_promo , biz02_person WHERE biz01_promo_id = biz02_promo_id GROUP BY biz01_buy_id ) c ON c.biz01_buy_id = a.bmt01_buy_id WHERE 1=1 AND #{personId} IN (bmt01_person_id, bmt01_reg_emp_id) AND bmt01_company_id = #{companyId}
AND a.bmt01_buy_qty - COALESCE(c.biz02_count, 0) != 0
AND bmt01_buy_date BETWEEN #{startDate} AND #{closeDate} ORDER BY bmt01_buy_date DESC

mapper.update:
UPDATE bmt01_buy
   SET bmt01_buy_date           = #{req.buyDate}
     , bmt01_provide_content_cd = #{req.provideContentCode}
     , bmt01_buy_qty            = #{req.buyQty}
     , bmt01_buy_amt            = #{req.buyAmt}
     , bmt01_person_id          = #{req.personId}
 WHERE bmt01_buy_id     = #{buyId}
   AND bmt01_company_id = #{companyId}

mapper.delete:
DELETE FROM bmt01_buy
 WHERE bmt01_company_id = #{companyId}
   AND bmt01_buy_id IN
   #{id}
